bruteForceSolution.code:
function patternBinaryTriangle(n) {
  let rows = [];
  for (let r = 0; r < n; r++) {
    let row = '';
    for (let c = 0; c <= r; c++) {
      row += ((r + c) % 2 === 0) ? '1' : '0';
    }
    rows.push(row);
  }
  return rows.join('\n');
}

