function patternBinaryTriangle(n) {
  let rows = [];
  for (let r = 0; r < n; r++) {
    let row = '';
    let start = r % 2 === 0 ? '1' : '0';
    for (let c = 0; c <= r; c++) {
      row += start;
      start = start === '1' ? '0' : '1';
    }
    rows.push(row);
  }
  return rows.join('\n');
}
